const statuses=['Pending','Stayed','Disposed','Done','Archived','Reopened'];
const legacyFields=['parties','institution','advocate'];
const writable=[...fields,...legacyFields,'assignedOfficerEmail','extensionStatus','extensionRequestedOn','extensionGrantedOn','extensionOrderReference','extensionReason','chronologyException'];
const limits={number:100,eofficeFileNo:200,officer:200,assignedOfficerEmail:254,status:20,deadlineType:500,source:2000,extensionStatus:20,extensionRequestedOn:10,extensionGrantedOn:10,extensionOrderReference:2000,extensionReason:2000,chronologyException:1000};
