async function database(env,ctx){const obj=await env.BUCKET.get(keyFor(ctx));if(obj)return {doc:JSON.parse(await obj.text()),etag:obj.etag};return {doc:{schema:2,revision:0,cases:await legacyRecords(env,ctx.user),requests:{}},etag:null};}
async function list(env,ctx){const {doc}=await database(env,ctx);return doc.cases.filter(c=>canRead(ctx,c)).map(c=>({...c,version:Number.isInteger(c.version)?c.version:0})).sort((a,b)=>(b.updated||'').localeCompare(a.updated||''));}
async function boundedJson(req){if(!req.headers.get('content-type')?.match(/^application\/json(?:\s*;\s*charset\s*=\s*(?:utf-8|"utf-8"))?\s*$/i))throw fail('Content-Type must be application/json',415);if(+(req.headers.get('content-length')||0)>65536)throw fail('Request exceeds 64 KiB',413);const reader=req.body?.getReader();if(!reader)throw fail('JSON body required');let n=0,chunks=[];while(true){const {value,done}=await reader.read();if(done)break;n+=value.byteLength;if(n>65536){await reader.cancel();throw fail('Request exceeds 64 KiB',413);}chunks.push(value);}const bytes=new Uint8Array(n);let i=0;for(const x of chunks){bytes.set(x,i);i+=x.length;}try{return JSON.parse(new TextDecoder('utf-8',{fatal:true}).decode(bytes))}catch{throw fail('Malformed JSON');}}
async function digest(v){return [...new Uint8Array(await crypto.subtle.digest('SHA-256',new TextEncoder().encode(JSON.stringify(v))))].map(x=>x.toString(16).padStart(2,'0')).join('');}
