 for(const [i,h0]of historyArray(cfg.history).entries()){const h=h0||{};rows.push({auditId:h.id||'legacy-access:'+i,at:h.at||'',caseId:'',caseNumber:'',currentCaseNumber:'',eofficeFileNo:'',operation:'Access changed',field:'Role: '+(h.email||missingAudit),before:h.before??missingAudit,after:h.after??missingAudit,actor:h.actor?.email||missingAudit,actorName:h.actor?.name||missingAudit,actorRole:h.actorRole||missingAudit,reason:h.reason||missingAudit,supportingReference:'',referenceDate:'',version:'',legacy:!h.id});}
