function auditFilters(input){objectInput(input,['q','from','to','actor','operation','field']);const f={};for(const k of ['q','from','to','actor','operation','field']){f[k]=input[k]===undefined?'':textValue(input[k],k);if(f[k].length>300)throw fail('Audit filter exceeds 300 characters');}validDate(f.from,'from');validDate(f.to,'to');if(f.from&&f.to&&f.from>f.to)throw fail('From date must precede To date');return f;}
