async function auditQuery(env,ctx,params){requireAdmin(ctx);for(const k of params.keys())if(!['q','from','to','actor','operation','field','page'].includes(k)||params.getAll(k).length!==1)throw fail('Invalid audit query parameter');const f=auditFilters(Object.fromEntries([...params].filter(([k])=>k!=='page')));const page=Number(params.get('page')||0);if(!Number.isInteger(page)||page<0||page>100000)throw fail('Invalid audit page');const {doc}=await database(env,ctx);const rows=filteredAudit(auditRows(doc,ctx.cfg),f);return {rows:rows.slice(page*50,page*50+50),total:rows.length,page,pageSize:50,filters:f};}
