const auditSelectedFilters=()=>Object.fromEntries(new FormData($('auditFilters')));
function auditTime(at){return at&&Number.isFinite(Date.parse(at))?new Date(at).toLocaleString('en-IN',{timeZone:'Asia/Kolkata'})+' IST':'Not recorded in legacy history';}
async function loadAudit(){const seq=++auditSeq;try{const params=new URLSearchParams({...auditSelectedFilters(),page:auditPage});$('auditStatus').textContent='Loading audit history…';const r=await fetch('/api/audit?'+params);const d=await r.json();if(seq!==auditSeq)return;if(!r.ok)throw Error(d.error);if(auditPage&&auditPage*50>=d.total){auditPage=Math.max(0,Math.ceil(d.total/50)-1);return loadAudit();}$('auditStatus').textContent=d.total+' changed-field / event rows';$('auditPrev').disabled=!auditPage;$('auditNext').disabled=(auditPage+1)*50>=d.total;$('auditPageLabel').textContent='Page '+(auditPage+1)+' of '+Math.max(1,Math.ceil(d.total/50));$('auditTable').innerHTML=d.rows.length?'<table><thead><tr>'+['When / audit ID','Case / E-office','Action / field','Previous value','New value','Changed by','Reason / reference'].map(h=>'<th>'+h+'</th>').join('')+'</tr></thead><tbody>'+d.rows.map(r=>'<tr><td>'+esc(auditTime(r.at))+'<p>'+esc(r.auditId)+'</p><p>Version: '+esc(r.version)+'</p></td><td><b>'+esc(r.caseNumber||'Register-wide')+'</b><p>Current: '+esc(r.currentCaseNumber)+'</p><p>'+esc(r.eofficeFileNo)+'</p><p>ID: '+esc(r.caseId)+'</p></td><td>'+esc(r.operation)+'<p><b>'+esc(labels[r.field]||r.field)+'</b></p></td><td style="white-space:pre-wrap;overflow-wrap:anywhere;max-width:260px">'+esc(r.before===''?'[Empty]':r.before)+'</td><td style="white-space:pre-wrap;overflow-wrap:anywhere;max-width:260px">'+esc(r.after===''?'[Empty]':r.after)+'</td><td>'+esc(r.actor)+'<p>'+esc(r.actorName)+'</p><p>'+esc(r.actorRole)+'</p></td><td>'+esc(r.reason)+'<p>'+esc(r.supportingReference)+'</p><p>'+esc(r.referenceDate)+'</p></td></tr>').join('')+'</tbody></table>':'<p class="empty">No audit entries match these filters.</p>';}catch(e){if(seq===auditSeq){$('auditStatus').textContent=e.message;$('auditTable').innerHTML='';$('auditPrev').disabled=true;$('auditNext').disabled=true;}}}
